mapper.select:
select *
from recycle_bin
where recycle_id = #{recycleId}
  and user_id = #{userId}
  and permanently_deleted = '0'

mapper.delete:
delete from recycle_bin
where recycle_id = #{recycleId}
  and user_id = #{userId}

mapper.update:
update recycle_bin
set permanently_deleted = '2',
    permanent_delete_time = sysdate()
where recycle_id = #{recycleId}
  and user_id = #{userId}
